INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q617409', 'Argentine War of Independence', 'The Argentine War of Independence (Spanish: guerra de la independencia argentina) was a set of military events from 1810 to 1825 which resulted in the consolidation of Argentina as an independent country from Spanish rule. The historiographical term encompasses battles and military feats such as the Crossing of the Andes.', 1810, NULL, NULL, 1816, NULL, NULL, 'year', '1810–1816', 65, 'https://en.wikipedia.org/wiki/Argentine_War_of_Independence'),
  ('Q2511385', 'Primera Junta y messi', 'The Primera Junta ("First Junta"), or Junta Provisional Gubernativa de las Provincias del Río de la Plata ("Provisional Governing Junta of the Provinces of the Río de la Plata"), is the most common name given to the first government of what would eventually become Argentina. It was formed on 25 May 1810, as a result of the events of the May Revolution.', 1810, 5, 25, NULL, NULL, NULL, 'day', '25 May 1810', 52, 'https://en.wikipedia.org/wiki/Primera_Junta'),
  ('Q4872286', 'Battle of San Nicolás', 'The Battle of San Nicolás was a naval engagement on 2 March 1811 on the Paraná River between the Spanish royalists from Montevideo, and the first flotilla created by the revolutionary government of Buenos Aires. It was the first engagement between the two fleets in the Río de la Plata region since the revolution, and a royalist victory.', 1811, 3, 2, NULL, NULL, NULL, 'day', '2 March 1811', 34, 'https://en.wikipedia.org/wiki/Battle_of_San_Nicol%C3%A1s'),
  ('Q2890270', 'Battle of Tucumán', 'The Battle of Tucumán was fought on 24 and 25 September 1812 near the Argentine city of San Miguel de Tucumán, during the Argentine War of Independence. The Army of the North, commanded by General Manuel Belgrano, defeated the royalist troops commanded by General Pío de Tristán, who had a two-to-one advantage in numbers, halting the royalist advance on Argentina''s northwest.', 1812, 9, 25, NULL, NULL, NULL, 'day', '25 September 1812', 41, 'https://en.wikipedia.org/wiki/Battle_of_Tucum%C3%A1n'),
  ('Q592091', 'Battle of Salta', 'The Battle of Salta took place on February 20, 1813, on the plains of Castañares, north of the present-day Argentine city of Salta, during the Argentine War of Independence. The Army of the North, under the command of general Manuel Belgrano, defeated for the second time the royalist troops of general Pío de Tristán, after their victory in the previous September at the Battle of Tucumán.', 1813, 2, 20, NULL, NULL, NULL, 'day', '20 February 1813', 43, 'https://en.wikipedia.org/wiki/Battle_of_Salta'),
  ('Q3268356', 'Battle of San Lorenzo', 'The Battle of San Lorenzo was fought on 3 February 1813 in San Lorenzo, Argentina, then part of the United Provinces of the Río de la Plata. The royalist troops were composed of militiamen recruited in Montevideo under the command of militia captain Antonio Zabala, who were defeated by the Regiment of Mounted Grenadiers under the command of José de San Martín.', 1813, 2, 3, NULL, NULL, NULL, 'day', '3 February 1813', 47, 'https://en.wikipedia.org/wiki/Battle_of_San_Lorenzo'),
  ('Q2697981', 'Argentine Civil Wars', 'The Argentine Civil Wars (Spanish: Guerras civiles argentinas) were a series of civil conflicts of varying intensity that took place from 1814 to 1853 in the territories of Argentina. Beginning concurrently with the Argentine War of Independence (1810 to 1818), the conflicts prevented the formation of a stable governing body until the signing of the Argentine Constitution of 1853, followed by low-frequency skirmishes that ended with the Federalization of Buenos Aires in 1880.', 1814, NULL, NULL, 1880, NULL, NULL, 'year', '1814–1880', 57, 'https://en.wikipedia.org/wiki/Argentine_Civil_Wars'),
  ('Q3248484', 'Argentine Declaration of Independence', 'What today is commonly referred as the Independence of Argentina was declared on July 9, 1816, by the Congress of Tucumán. In reality, the congressmen who were assembled in Tucumán declared the independence of the United Provinces of South America, which is one of the official names of the Argentine Republic.', 1816, 7, 9, NULL, NULL, NULL, 'day', '9 July 1816', 50, 'https://en.wikipedia.org/wiki/Argentine_Declaration_of_Independence'),
  ('Q1851266', 'Battle of Cepeda', 'The Battle of Cepeda of 1820 took place on February 1 in Cañada de Cepeda, Buenos Aires Province, Argentina. The conflict was the first major battle that saw Unitarians and Federals as two constituted sides.', 1820, 2, 1, NULL, NULL, NULL, 'day', '1 February 1820', 41, 'https://en.wikipedia.org/wiki/Battle_of_Cepeda_(1820)'),
  ('Q2060982', 'Battle of Famaillá', 'The Battle of Famaillá (Famaillá, Tucumán Province, Argentina, September 19, 1841), was a Federal Party victory, under the command of former Uruguayan president Manuel Oribe, over the army of the Unitarian Party under general Juan Lavalle, during the Argentine Civil War.', 1841, 9, 19, NULL, NULL, NULL, 'day', '19 September 1841', 37, 'https://en.wikipedia.org/wiki/Battle_of_Famaill%C3%A1'),
  ('Q2890596', 'Battle of Vuelta de Obligado', 'The Battle of Vuelta de Obligado took place on 20 November 1845, in the waters of the Paraná River, on its right bank and in the north of the province of Buenos Aires (Argentina), in a bend where the river narrows and turns, known as Vuelta de Obligado, in what is today the town of Obligado, in San Pedro district. It was a confrontation between the province of Buenos Aires, governed by Brigadier Juan Manuel de Rosas – who appointed General Lucio Norberto Mansilla as commander of the defense forces – and the Anglo-French squadron, whose intervention was carried out under the pretext of…', 1845, 11, 20, NULL, NULL, NULL, 'day', '20 November 1845', 51, 'https://en.wikipedia.org/wiki/Battle_of_Vuelta_de_Obligado'),
  ('Q3042457', 'Platine War', 'The Platine War (Spanish: Guerra Platina, Portuguese: Guerra do Prata, Guerra contra Oribe e Rosas; 18 August 1851 – 3 February 1852) was fought between the Argentine Confederation and an alliance consisting of the Empire of Brazil, Uruguay, and the Argentine provinces of Entre Ríos and Corrientes, with the participation of the Republic of Paraguay as Brazil''s co-belligerent and ally. The war was part of a decades-long dispute between Argentina and Brazil for influence over Uruguay and Paraguay, and hegemony over the Platine region (areas bordering the Río de la Plata).', 1851, 8, 18, 1852, 2, 3, 'day', '18 August 1851 – 3 February 1852', 53, 'https://en.wikipedia.org/wiki/Platine_War'),
  ('Q5723335', 'Battle of the Tonelero Pass', 'The Battle of the Tonelero Pass, also known as Passage of the Tonelero, was a battle in the Platine War fought near the cliff of Acevedo, in the west bank of the Paraná River, Argentina, on 17 December 1851, between the Argentine Confederation Army commanded by Lucio Norberto Mansilla and warships of the Brazilian Imperial Navy led by John Pascoe Grenfell. That day the Brazilian fleet commanded by Grenfell was near the cliff of Acevedo in the river Paraná, with the intention to break through the Argentine defenses at the Tonelero pass.', 1851, 12, 17, NULL, NULL, NULL, 'day', '17 December 1851', 37, 'https://en.wikipedia.org/wiki/Battle_of_the_Tonelero_Pass'),
  ('Q616931', 'Battle of Caseros', 'The Battle of Caseros (Spanish: Batalla de Caseros; Portuguese: Batalha de Caseros) was fought near the town of El Palomar, Argentina, on 3 February 1852, between forces of the Argentine Confederation, commanded by Juan Manuel de Rosas, and a coalition consisting of the Argentine provinces of Entre Ríos and Corrientes, the Empire of Brazil, and Uruguay. The allied forces, known as the Grand Army (Ejército Grande), defeated Rosas, who fled to the United Kingdom.', 1852, 2, 3, NULL, NULL, NULL, 'day', '3 February 1852', 53, 'https://en.wikipedia.org/wiki/Battle_of_Caseros'),
  ('Q8051877', 'yellow fever in Buenos Aires', 'The Yellow fever in Buenos Aires was a series of epidemics that took place in 1852, 1858, 1870 and 1871, the latter being a disaster that killed about 8% of Porteños: in a city where the daily death rate was less than 20, there were days that killed more than 500 people. The Yellow Fever would have come from Asunción, Paraguay, brought by Argentine soldiers returning from the war just fought in that country, having previously spread in the city of Corrientes.', 1852, NULL, NULL, 1871, NULL, NULL, 'year', '1852–1871', 45, 'https://en.wikipedia.org/wiki/Yellow_fever_in_Buenos_Aires'),
  ('Q76914', 'Battle of Cepeda', 'The Battle of Cepeda of 1859 took place on October 23 at Cañada de Cepeda, Buenos Aires Province, Argentina. The Argentine Confederation army, led by federalist Justo José de Urquiza defeated the State of Buenos Aires forces, led by unitarian Bartolomé Mitre.', 1859, 10, 23, NULL, NULL, NULL, 'day', '23 October 1859', 41, 'https://en.wikipedia.org/wiki/Battle_of_Cepeda_(1859)'),
  ('Q832683', 'Battle of Pavón', 'The Battle of Pavón, a key battle of the Argentine Civil Wars, was fought in Pavón, Santa Fé Province, Argentina on 17 September 1861 between the Army of the State of Buenos Aires (commanded by Bartolomé Mitre) and the Army of Republic of the Argentine Confederation (commanded by Justo José de Urquiza). The withdrawal of Urquiza left the field to Mitre.', 1861, 9, 17, NULL, NULL, NULL, 'day', '17 September 1861', 48, 'https://en.wikipedia.org/wiki/Battle_of_Pav%C3%B3n'),
  ('Q4555068', '1861 Mendoza earthquake', 'The 1861 Mendoza earthquake occurred in the province of Mendoza, Argentina on 20 March at 11:30 PM. It had an estimated magnitude of 7.2 on the Ms scale and an intensity of IX–X on the Mercalli scale. Its hypocenter was located at an estimated depth of 30 kilometres (19 mi).', 1861, 3, 20, NULL, NULL, NULL, 'day', '20 March 1861', 37, 'https://en.wikipedia.org/wiki/1861_Mendoza_earthquake'),
  ('Q2236812', 'Battle of Riachuelo', 'The Battle of Riachuelo (or Battle of the Riachuelo) was a large and decisive naval battle of the Paraguayan War between Paraguay and the Empire of Brazil. By late 1864, Paraguay had scored a series of victories in the war, but on 11 June 1865, its naval defeat by the Brazilians on the Paraná River began to turn the tide in favor of the allies.', 1865, 6, 11, NULL, NULL, NULL, 'day', '11 June 1865', 52, 'https://en.wikipedia.org/wiki/Battle_of_Riachuelo'),
  ('Q3775020', 'Battle of Yatay', 'In the Paraguayan War, the Battle of Yatay was fought on August 17, 1865, between the troops of the Triple Alliance (Argentina, Brazil and (Uruguay) and the soldiers of Paraguay near Paso de los Libres, Corrientes, Argentina. It was a victory for the Alliance.', 1865, 8, 17, NULL, NULL, NULL, 'day', '17 August 1865', 41, 'https://en.wikipedia.org/wiki/Battle_of_Yatay'),
  ('Q5722782', 'Battle of Corrales', 'The Battle of Pehuajó, also known as Battle of Corrales or Battle of Itati, was fought during the Paraguayan War on 31 January 1866. Around 1,500 Paraguayan troops commanded by general Francisco Isidoro Resquín and lieutenant Celestino Prieto engaged in a surprise attack against a couple of advanced Argentine and Uruguayan battalions with about 2,000 men led by general Emilio Conesa, under direct command of the president of Argentina, Bartolomé Mitre.', 1866, 1, 31, NULL, NULL, NULL, 'day', '31 January 1866', 34, 'https://en.wikipedia.org/wiki/Battle_of_Pehuaj%C3%B3'),
  ('Q4135525', 'Selknam genocide', 'The Selkʼnam genocide was the systematic extermination of the Selkʼnam people, one of the four indigenous peoples of Tierra del Fuego archipelago, in the late 19th and early 20th centuries. Historians estimate that the genocide spanned a period of between ten and twenty years, and resulted in the decline of the Selkʼnam population from approximately 4,000 people during the 1880s to a few hundred by the early 1900s.', 1880, NULL, NULL, 1910, NULL, NULL, 'year', '1880–1910', 48, 'https://en.wikipedia.org/wiki/Selk%CA%BCnam_genocide'),
  ('Q940076', 'Boundary treaty of 1881 between Chile and Argentina', 'The Boundary Treaty of 1881 (Spanish: Tratado de Límites de 1881) between Argentina and Chile was signed on 23 July 1881 in Buenos Aires by Bernardo de Irigoyen, for Argentina, and Francisco de Borja Echeverría, for Chile, with the aim of establishing a precise border between the two countries based on the uti possidetis juris principle. Despite dividing largely unexplored lands, the treaty laid the groundwork for nearly all of Chile''s and Argentina''s 5600 km current border.', 1881, 7, 23, NULL, NULL, NULL, 'day', '23 July 1881', 41, 'https://en.wikipedia.org/wiki/Boundary_Treaty_of_1881_between_Chile_and_Argentina'),
  ('Q1348983', 'Conquest of the Desert', 'The Conquest of the Desert (Spanish: Conquista del desierto) was an Argentine military campaign directed mainly by General Julio Argentino Roca during the 1870s and 1880s with the intention of establishing dominance over Patagonia, inhabited primarily by Indigenous peoples. The Conquest of the Desert extended Argentine territories into Patagonia and ended Chilean expansion in the region.', 1884, NULL, NULL, NULL, NULL, NULL, 'year', '1884', 59, 'https://en.wikipedia.org/wiki/Conquest_of_the_Desert'),
  ('Q634483', '1888 Río de la Plata earthquake', 'The 1888 Río de la Plata earthquake occurred on 5 June measuring 5.5 on the Richter scale, and shook the upper Río de la Plata at 3:20 UTC-3. The epicentre was located 15 kilometres (9 mi) southwest of Colonia del Sacramento (Uruguay) and 42 kilometres (26 mi) east of Buenos Aires (Argentina), with a hypocentre at a depth of 30 kilometres (19 mi).', 1888, 6, 5, NULL, NULL, NULL, 'day', '5 June 1888', 37, 'https://en.wikipedia.org/wiki/1888_R%C3%ADo_de_la_Plata_earthquake'),
  ('Q3294643', 'Revolution of the Park', 'The Revolution of the Park (Revolución del Parque), also known as the Revolution of 1890 or Revolution of ''90, was a civic-military uprising against the national government of Argentina that took place from July 26 to 29, 1890. The revolution began with the takeover of the Buenos Aires Artillery Park (Parque de Artillería), located in what is today Lavalle Square.', 1890, 7, 26, NULL, NULL, NULL, 'day', '26 July 1890', 47, 'https://en.wikipedia.org/wiki/Revolution_of_the_Park'),
  ('Q160011', 'Battle of the Falkland Islands', 'The Battle of the Falkland Islands was a First World War naval action between the British Royal Navy and Imperial German Navy on 8 December 1914 in the South Atlantic. The British, after their defeat at the Battle of Coronel on 1 November, sent a large force to track down and destroy the German cruiser squadron.', 1914, 12, 8, NULL, NULL, NULL, 'day', '8 December 1914', 70, 'https://en.wikipedia.org/wiki/Battle_of_the_Falkland_Islands'),
  ('Q6553389', 'Patagonia rebelde', 'Patagonia Rebelde (or Patagonia Trágica) ("Rebel Patagonia" or "Tragic Patagonia" in English) was the name given to the uprising and violent suppression of a rural workers'' strike in the Argentine province of Santa Cruz in Patagonia between 1920 and 1922. The uprising was put down by Colonel Héctor Benigno Varela''s 10th Cavalry Regiment of the Argentine Army under the orders of President Hipólito Yrigoyen.', 1921, 12, NULL, 1922, NULL, NULL, 'month', 'December 1921 – 1922', 47, 'https://en.wikipedia.org/wiki/Patagonia_Rebelde'),
  ('Q1239076', 'Napalpí massacre', 'The Napalpí massacre occurred on 19 July 1924, in Napalpí, a rural village in the Chaco Province of Northeast Argentina. It involved the massacre of 400 Indigenous people of the Toba and Mocoví ethnicity by the Argentine Police and ranchers.', 1924, 7, 19, NULL, NULL, NULL, 'day', '19 July 1924', 37, 'https://en.wikipedia.org/wiki/Napalp%C3%AD_massacre'),
  ('Q3295615', 'Infamous Decade', 'The Infamous Decade (Spanish: Década Infame) was a period in Argentine history that began with the 1930 coup d''état against President Hipólito Yrigoyen. This decade was marked on one hand by significant rural exodus, with many small rural landowners ruined by the Great Depression, which in turn pushed the country towards import substitution industrialization, and on the other hand, conservative governments stayed in power perpetually by electoral fraud.', 1930, 9, 6, 1943, 6, 4, 'day', '6 September 1930 – 4 June 1943', 52, 'https://en.wikipedia.org/wiki/Infamous_Decade'),
  ('Q4402025', '1930 Argentine coup', 'The 1930 Argentine coup d''état, also known as the September Revolution by its supporters, involved the overthrow of the Argentine government of Hipólito Yrigoyen by forces loyal to General José Félix Uriburu. The coup took place on 6 September 1930 when Uriburu led a small detachment of troops into the capital, experiencing no substantial opposition and taking control of the Casa Rosada.', 1930, 9, 6, NULL, NULL, NULL, 'day', '6 September 1930', 45, 'https://en.wikipedia.org/wiki/1930_Argentine_coup_d''%C3%A9tat'),
  ('Q131673464', 'Golden Age of Argentine cinema', 'The Golden Age of Argentine cinema (Spanish: Época de Oro del cine argentino or other equivalent names), sometimes known interchangeably as the broader classical or classical-industrial period (Spanish: período clásico-industrial), is an era in the history of the cinema of Argentina that began in the 1930s and lasted until the 1940s or 1950s, depending on the definition, during which national film production underwent a process of industrialization and standardization that involved the emergence of mass production, the establishment of the studio, genre and star systems, and the adoption of…', 1933, NULL, NULL, 1956, NULL, NULL, 'year', '1933–1956', 52, 'https://en.wikipedia.org/wiki/Golden_Age_of_Argentine_cinema'),
  ('Q4565209', '1943 Argentine coup d''état', 'The 1943 Argentine Revolution (also known as the 1943 Argentine coup d''état, the June Revolution or the Revolution of ''43) was a coup d''état on 4 June 1943 that ended the government of Ramón Castillo, who had been fraudulently elected to the office of vice-president before succeeding to the presidency in 1942 as part of the period known as the Infamous Decade. The coup d''état was launched by the lodge "United Officers'' Group" (GOU), a secret military organization of nationalist nature.', 1943, 6, 4, NULL, NULL, NULL, 'day', '4 June 1943', 51, 'https://en.wikipedia.org/wiki/1943_Argentine_Revolution'),
  ('Q3505891', '1944 San Juan Earthquake', 'The 1944 San Juan earthquake took place on 15 January in the province of San Juan, in the center-west area of Argentina, a region highly prone to seismic events. This moderate to strong earthquake (estimated moment magnitudes range from 6.7 to 7.8) destroyed a large part of San Juan, the provincial capital, and killed 10,000 of its inhabitants, 10 percent of its population at the time.', 1944, 1, 15, NULL, NULL, NULL, 'day', '15 January 1944', 47, 'https://en.wikipedia.org/wiki/1944_San_Juan_earthquake'),
  ('Q4566340', '1948 Salta earthquake', 'The 1948 Salta earthquake took place in the Argentinian province of Salta on 25 August at 03:09:28 local time The shock was 7.0 on the moment magnitude scale and had a maximum Mercalli Intensity of IX (Violent). Property damage and casualties occurred in several towns in the east and southeast of Salta, and also in northern Tucumán and Jujuy, affecting the capitals of both.', 1948, 8, 25, NULL, NULL, NULL, 'day', '25 August 1948', 37, 'https://en.wikipedia.org/wiki/1948_Salta_earthquake'),
  ('Q2834857', '1949 Tierra del Fuego earthquake', 'The 1949 Tierra del Fuego earthquakes occurred slightly more than eight hours apart on 17 December. Their epicenters were located in the east of the Chilean Tierra del Fuego Province, close to the Argentine border on the island of Tierra del Fuego.', 1949, 12, 17, NULL, NULL, NULL, 'day', '17 December 1949', 37, 'https://en.wikipedia.org/wiki/1949_Tierra_del_Fuego_earthquakes'),
  ('Q891808', 'Bombing of Plaza de Mayo', 'On 16 June 1955, 30 aircraft from the Argentine Navy and Air Force bombed and strafed Plaza de Mayo, the main square of the Argentine capital Buenos Aires. The attack targeted the adjacent Casa Rosada, the seat of government, while a large crowd demonstrated in support of the president, Juan Perón.', 1955, 6, 16, NULL, NULL, NULL, 'day', '16 June 1955', 47, 'https://en.wikipedia.org/wiki/Bombing_of_Plaza_de_Mayo'),
  ('Q2504085', 'Rosariazo', 'The Rosariazo (Spanish pronunciation: [rosaˈɾjaso]) was a protest movement that consisted in demonstrations and strikes, in Rosario, province of Santa Fe, Argentina, between May and September 1969, during the military dictatorial rule of de facto President General Juan Carlos Onganía. The Rosariazo was caused by events in other parts of Argentina, and in turn triggered similar protests itself.', 1969, NULL, NULL, 1969, 9, NULL, 'year', '1969', 41, 'https://en.wikipedia.org/wiki/Rosariazo'),
  ('Q737967', '1972 Andes flight disaster', 'Uruguayan Air Force Flight 571 was the chartered flight of a Fairchild FH-227D from Montevideo, Uruguay, to Santiago, Chile, that crashed in the Andes mountains in Argentina on 13 October 1972. The accident and subsequent survival became known as both the Andes flight disaster (Tragedia de los Andes, literally Tragedy of the Andes) and the Miracle of the Andes (Milagro de los Andes).', 1972, 10, 13, NULL, NULL, NULL, 'day', '13 October 1972', 69, 'https://en.wikipedia.org/wiki/Uruguayan_Air_Force_Flight_571'),
  ('Q3036457', 'Trelew massacre', 'The Trelew Massacre was a mass execution of 16 political prisoners, militants of different Peronist and leftist organizations, in Rawson prison by the military dictatorship of Argentina. The prisoners were recaptured after an escape attempt and subsequently shot down by marines led by Lieutenant Commander Luis Emilio Sosa in a simulated new attempt to escape.', 1972, 8, 22, NULL, NULL, NULL, 'day', '22 August 1972', 43, 'https://en.wikipedia.org/wiki/Trelew_massacre'),
  ('Q1210277', 'Ezeiza masacre', 'The Ezeiza massacre (Spanish pronunciation: [eˈsejsa]) took place on June 20, 1973, at Puente 12, the intersection of General Ricchieri freeway (the Ezeiza Airport access) and Camino de Cintura (provincial route 4), some 10 km from Ezeiza International Airport in Buenos Aires, Argentina. Peronist masses, including many young people, had gathered there to acclaim Juan Perón''s definitive return from an 18-year exile in Spain.', 1973, 6, 20, NULL, NULL, NULL, 'day', '20 June 1973', 53, 'https://en.wikipedia.org/wiki/Ezeiza_massacre'),
  ('Q645986', 'National Reorganization Process', 'The National Reorganization Process (Spanish: Proceso de Reorganización Nacional, PRN; often simply el Proceso, "the Process") was the military dictatorship that ruled Argentina from the coup d''état of 24 March 1976 until the transfer of power on 10 December 1983 to a government elected at the 1983 general election. In Argentina it is often known simply as the última junta militar ("last military junta"), última dictadura militar ("last military dictatorship"), última dictadura cívico-militar ("last civil–military dictatorship"), or última dictadura cívico-eclesial-militar ("last…', 1976, 3, 24, 1983, 12, 10, 'day', '24 March 1976 – 10 December 1983', 69, 'https://en.wikipedia.org/wiki/National_Reorganization_Process'),
  ('Q958575', 'Massacre of Margarita Belén', 'The Margarita Belén Massacre (Spanish: Masacre de Margarita Belén) took place during the Dirty War in Argentina. It involved the torture and execution of 22 Montoneros, some of whom were killed after surrendering and laying down their weapons near the town of Margarita Belén, Chaco Province, on 13 December 1976, in a joint operation of the Argentine Army and the Chaco Provincial Police.', 1976, 12, 13, NULL, NULL, NULL, 'day', '13 December 1976', 37, 'https://en.wikipedia.org/wiki/Margarita_Bel%C3%A9n_massacre'),
  ('Q1048750', '1976 Argentine coup d''état', 'A coup d''état overthrew Isabel Perón as President of Argentina on 24 March 1976. A military junta was installed to replace her; this was headed by Lieutenant General Jorge Rafael Videla, Admiral Emilio Eduardo Massera, and Brigadier-General Orlando Ramón Agosti.', 1976, 3, 24, NULL, NULL, NULL, 'day', '24 March 1976', 57, 'https://en.wikipedia.org/wiki/1976_Argentine_coup_d''%C3%A9tat'),
  ('Q3393737', 'San Patricio Church massacre', 'The San Patricio Church massacre was the mass murder of three priests and two seminarians of the Pallottine order on July 4, 1976, during the Dictadura Cívico Militar Argentina, at St. Patrick''s Church, located in the Belgrano neighborhood of the Buenos Aires, Argentina.', 1976, 7, 4, NULL, NULL, NULL, 'day', '4 July 1976', 37, 'https://en.wikipedia.org/wiki/San_Patricio_Church_massacre'),
  ('Q4345906', 'Invasion of South Georgia', 'The invasion of South Georgia, also known as the Battle of Grytviken or Operation Georgias, took place on 3 April 1982, when Argentine Navy forces seized control of the east coast of South Georgia after overpowering a small group of Royal Marines at Grytviken. Though outnumbered, the Royal Marines shot down a helicopter and hit the Argentine corvette ARA Guerrico several times before being forced to surrender.', 1982, 4, 3, NULL, NULL, NULL, 'day', '3 April 1982', 43, 'https://en.wikipedia.org/wiki/Invasion_of_South_Georgia'),
  ('Q4872617', 'Battle of Two Sisters', 'The Battle of Two Sisters was a night attack by British Royal Marines on Argentine positions during the Falklands War. It took place on 11–12 June 1982 on Two Sisters, a ridge with two peaks near Stanley.', 1982, 6, 11, 1982, 6, 12, 'day', '11 June 1982 – 12 June 1982', 34, 'https://en.wikipedia.org/wiki/Battle_of_Two_Sisters'),
  ('Q1455864', 'Treaty of Peace and Friendship of 1984 between Chile and Argentina', 'The Treaty of Peace and Friendship of 1984 between Chile and Argentina (Spanish: Tratado de Paz y Amistad de 1984 entre Chile y Argentina, see the text in the United Nations) was signed into agreement at the Vatican on 29 November 1984. It was ratified on 30 December 1984 by the Argentine Chamber of Deputies; on 15 March 1985 by the Argentine National Congress; on 16 March 1985 by the Interim representative of the President of Argentina, who was abroad; on 11 April 1985 by the Chilean Military Government Junta as Legislature.', 1984, 11, 29, NULL, NULL, NULL, 'day', '29 November 1984', 37, 'https://en.wikipedia.org/wiki/Treaty_of_Peace_and_Friendship_of_1984_between_Chile_and_Argentina'),
  ('Q947194', 'carapintadas', 'The Carapintadas (English: Painted Faces) were a group of mutineers in the Argentine Army, who took part in various uprisings between 1987 and 1990 during the presidencies of Raúl Alfonsín and Carlos Menem in Argentina. The rebellions, while at first thought to be an attempt at a military coup, were staged primarily to assert displeasure against the civilian government and make certain military demands known.', 1987, NULL, NULL, 1990, NULL, NULL, 'year', '1987–1990', 39, 'https://en.wikipedia.org/wiki/Carapintadas'),
  ('Q322936', 'AMIA bombing', 'The Asociación Mutual Israelita Argentina (AMIA; transl. "Argentine Israelite Mutual Association"), a Jewish community center in Buenos Aires, Argentina, was bombed on 18 July 1994. Executed as a suicide attack, a bomb-laden van was driven into the AMIA building and subsequently detonated, killing 85 people and injuring over 300.', 1994, 7, 18, NULL, NULL, NULL, 'day', '18 July 1994', 62, 'https://en.wikipedia.org/wiki/AMIA_bombing'),
  ('Q645426', 'Argentine economic crisis', 'The 1998–2002 Argentine great depression was an economic depression in Argentina, which began in the third quarter of 1998 and lasted until the second quarter of 2002. It followed fifteen years of stagnation and a brief period of free-market reforms.', 1998, NULL, NULL, 2002, NULL, NULL, 'year', '1998–2002', 56, 'https://en.wikipedia.org/wiki/1998%E2%80%932002_Argentine_great_depression'),
  ('Q3317347', 'LAPA Flight 3142', 'LAPA Flight 3142 was a scheduled Buenos Aires–Córdoba flight operated by the Argentine airline Líneas Aéreas Privadas Argentinas. On 31 August 1999, the Boeing 737-200 operating the flight crashed while attempting to take off from Aeroparque Jorge Newbery International Airport in Buenos Aires.', 1999, 8, 31, NULL, NULL, NULL, 'day', '31 August 1999', 53, 'https://en.wikipedia.org/wiki/LAPA_Flight_3142'),
  ('Q5115965', 'December 2001 riots in Argentina', 'The December 2001 crisis, sometimes known as Cacerolazo or Argentinazo (pronounced [aɾxentiˈnaso]), was a period of civil unrest and rioting in Argentina, which took place during December 2001, with the most violent incidents taking place on 19 and 20 December in the capital, Buenos Aires, Rosario and other large cities around the country. It was preceded by a popular revolt against the Argentine government, rallying behind the motto "All of them must go!" (Spanish: ¡Que se vayan todos!), which caused the resignation of then-president Fernando de la Rúa, giving way to a period of political…', 2001, NULL, NULL, NULL, NULL, NULL, 'year', '2001', 45, 'https://en.wikipedia.org/wiki/December_2001_riots_in_Argentina'),
  ('Q1786733', 'República Cromañón nightclub fire', 'On 30 December 2004, a fire broke out in the crowded República Cromañón nightclub in Buenos Aires, Argentina, killing 194 people and leaving at least 1,492 injured. The direct cause was the indoor pyrotechnics igniting the ceiling.', 2004, 12, 30, NULL, NULL, NULL, 'day', '30 December 2004', 45, 'https://en.wikipedia.org/wiki/Croma%C3%B1%C3%B3n_nightclub_fire'),
  ('Q4610503', '2008 Argentine agrarian strike', 'The 2008 Argentine agrarian strike refers to the conflict between the Argentine national government and the 4 entities that represented the agriculture sector. The crisis began in March 2008 with four agricultural sector employers organizations (Federación Agraria Argentina, Sociedad Rural Argentina, Confederaciones Rurales Argentinas and CONINAGRO) taking direct action such as road blocks to protest against the decision of the government of Cristina Fernández de Kirchner to raise export taxes on soybeans and sunflower.', 2008, NULL, NULL, NULL, NULL, NULL, 'year', '2008', 34, 'https://en.wikipedia.org/wiki/2008_Argentine_agrarian_strike'),
  ('Q3621706', '2010 Salta earthquake', 'The 2010 Salta earthquake occurred on February 27 at 12:45:36 local time in Salta Province, Argentina and had a magnitude of 6.3. It occurred less than 12 hours after the far larger magnitude 8.8 Chile earthquake, which killed 525 people.', 2010, 2, 27, NULL, NULL, NULL, 'day', '27 February 2010', 41, 'https://en.wikipedia.org/wiki/2010_Salta_earthquake'),
  ('Q3499141', 'Sol Líneas Aéreas Flight 5428', 'Sol Líneas Aéreas Flight 5428 was a passenger flight which crashed near Los Menucos, Argentina, on 18 May 2011, killing all 22 people on board. The aircraft involved, a Saab 340, was operating Sol Líneas Aéreas'' scheduled domestic service from Neuquén to Comodoro Rivadavia.', 2011, 5, 18, NULL, NULL, NULL, 'day', '18 May 2011', 53, 'https://en.wikipedia.org/wiki/Sol_L%C3%ADneas_A%C3%A9reas_Flight_5428'),
  ('Q10310765', '2013 Argentina floods', 'Between 1 and 3 April 2013, the northeastern section of Buenos Aires Province, Argentina, experienced several flash floods that claimed the lives of 101 people. Greater La Plata was hardest hit with 91 reported deaths, and Greater Buenos Aires reported 10 deaths.', 2013, 4, 1, NULL, NULL, NULL, 'day', '1 April 2013', 39, 'https://en.wikipedia.org/wiki/2013_Argentina_floods'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q133254078', '2025 Bahia Blanca floods', 'On 7 March 2025, Bahía Blanca and neighboring cities, in the Province of Buenos Aires, Argentina, were flooded in the aftermath of unusually intense rainfall. The disaster caused serious material damage, thousands of evacuations, at least 17 deaths, and over 200 disappearances.', 2025, 3, 7, NULL, NULL, NULL, 'day', '7 March 2025', 39, 'https://en.wikipedia.org/wiki/2025_Bah%C3%ADa_Blanca_floods');
